package ar.edu.utn.frc.tup.piv.llm.infrastructure.persistence;
import java.util.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Repository;
@Repository public class ChallengeCalibrationAssignmentRepository {private final JdbcTemplate j;public ChallengeCalibrationAssignmentRepository(JdbcTemplate j){this.j=j;}public boolean assignActive(UUID challenge,UUID course){return j.update("insert into llm.challenge_calibration_assignments(challenge_id,course_id,calibration_run_id) select ?,?,a.calibration_run_id from llm.active_calibrations a join llm.calibration_runs r on r.id=a.calibration_run_id where a.course_id=? and r.state='PASSED'",challenge,course,course)==1;} public Preview preview(UUID course,UUID next){var rows=j.query("select challenge_id,calibration_run_id,locked_at from llm.challenge_calibration_assignments where course_id=?",(r,n)->new Row(r.getObject(1,UUID.class),r.getObject(2,UUID.class),r.getObject(3,java.time.OffsetDateTime.class)),course);var migrable=new java.util.ArrayList<UUID>();var locked=new java.util.ArrayList<UUID>();for(var x:rows)if(x.lockedAt()==null)migrable.add(x.id());else locked.add(x.id());return new Preview(List.copyOf(migrable),List.copyOf(locked));} public int migrate(UUID course,UUID run,Set<UUID> challenges){if(challenges.isEmpty())return 0;return j.update("update llm.challenge_calibration_assignments set calibration_run_id=?,assigned_at=now() where course_id=? and locked_at is null and challenge_id = any(?)",run,course,jdbcArray(challenges));} private java.sql.Array jdbcArray(Set<UUID> ids){try{return j.getDataSource().getConnection().createArrayOf("uuid",ids.toArray());}catch(Exception e){throw new IllegalStateException(e);}} public boolean lockOnFirstAttempt(UUID challenge,UUID attempt){return j.update("update llm.challenge_calibration_assignments set first_attempt_id=?,locked_at=now() where challenge_id=? and first_attempt_id is null",attempt,challenge)==1;} public record Preview(List<UUID> migrable, List<UUID> locked){} private record Row(UUID id,UUID run,java.time.OffsetDateTime lockedAt){}}
